// ── BOX PLOT (pure SVG) ──
(function() {
  const svg = document.getElementById('boxplot-svg');
  const W = 860, H = 320;
  const PAD = { top: 30, right: 30, bottom: 50, left: 60 };
  const plotW = W - PAD.left - PAD.right;
  const plotH = H - PAD.top - PAD.bottom;

  const data = [
    { label: 'E10',        color: '#2563eb', min: 104.1, q25: 136.9, median: 144.9, q75: 152.9, max: 201.0, whiskerLow: 112.9, whiskerHigh: 176.9, mean: 145.2 },
    { label: 'E5',         color: '#7c3aed', min: 120.0, q25: 151.9, median: 160.9, q75: 169.9, max: 213.0, whiskerLow: 124.9, whiskerHigh: 196.9, mean: 161.3 },
    { label: 'B7_STD',     color: '#059669', min: 106.4, q25: 149.9, median: 167.9, q75: 182.9, max: 230.4, whiskerLow: 106.4, whiskerHigh: 230.4, mean: 167.0 },
    { label: 'B7_PREM',    color: '#d97706', min: 100.0, q25: 169.9, median: 187.9, q75: 199.9, max: 244.4, whiskerLow: 124.9, whiskerHigh: 244.4, mean: 185.8 },
    { label: 'HVO',        color: '#dc2626', min: 144.0, q25: 173.9, median: 189.9, q75: 199.9, max: 226.9, whiskerLow: 144.0, whiskerHigh: 226.9, mean: 187.4 },
  ];

  const yMin = 100, yMax = 250;
  const yScale = v => PAD.top + plotH - ((v - yMin) / (yMax - yMin)) * plotH;
  const n = data.length;
  const bw = 50; // box width
  const xStep = plotW / n;
  const xPos = i => PAD.left + xStep * i + xStep / 2;

  let svgContent = `<g>`;

  // Y gridlines + labels
  for (let v = 100; v <= 250; v += 25) {
    const y = yScale(v);
    svgContent += `<line x1="${PAD.left}" y1="${y}" x2="${W - PAD.right}" y2="${y}" stroke="#e2e8f0" stroke-width="1"/>`;
    svgContent += `<text x="${PAD.left - 6}" y="${y + 4}" text-anchor="end" font-size="11" fill="#64748b">${v}</text>`;
  }

  // Y axis label
  svgContent += `<text transform="rotate(-90 ${PAD.left - 40} ${PAD.top + plotH/2})" x="${PAD.left - 40}" y="${PAD.top + plotH/2}" text-anchor="middle" font-size="11" fill="#64748b">Pence per litre (ppl)</text>`;

  data.forEach((d, i) => {
    const x = xPos(i);
    const col = d.color;
    const halfBW = bw / 2;

    // Whisker lines
    const wLow  = yScale(d.whiskerLow);
    const wHigh = yScale(d.whiskerHigh);
    svgContent += `<line x1="${x}" y1="${wHigh}" x2="${x}" y2="${yScale(d.q75)}" stroke="${col}" stroke-width="1.5" stroke-dasharray="4,2"/>`;
    svgContent += `<line x1="${x}" y1="${yScale(d.q25)}" x2="${x}" y2="${wLow}" stroke="${col}" stroke-width="1.5" stroke-dasharray="4,2"/>`;
    // Whisker caps
    svgContent += `<line x1="${x-12}" y1="${wHigh}" x2="${x+12}" y2="${wHigh}" stroke="${col}" stroke-width="1.5"/>`;
    svgContent += `<line x1="${x-12}" y1="${wLow}"  x2="${x+12}" y2="${wLow}"  stroke="${col}" stroke-width="1.5"/>`;

    // IQR box
    const boxTop = yScale(d.q75);
    const boxBot = yScale(d.q25);
    svgContent += `<rect x="${x - halfBW}" y="${boxTop}" width="${bw}" height="${boxBot - boxTop}" fill="${col}33" stroke="${col}" stroke-width="2" rx="3"/>`;

    // Median line
    const medY = yScale(d.median);
    svgContent += `<line x1="${x - halfBW}" y1="${medY}" x2="${x + halfBW}" y2="${medY}" stroke="${col}" stroke-width="2.5"/>`;

    // Mean diamond
    const meanY = yScale(d.mean);
    svgContent += `<polygon points="${x},${meanY-5} ${x+5},${meanY} ${x},${meanY+5} ${x-5},${meanY}" fill="${col}" opacity="0.8"/>`;

    // X label
    svgContent += `<text x="${x}" y="${H - PAD.bottom + 18}" text-anchor="middle" font-size="12" font-weight="600" fill="#334155">${d.label}</text>`;

    // Median value label
    svgContent += `<text x="${x + halfBW + 4}" y="${medY + 4}" font-size="10" fill="${col}" font-weight="600">${d.median}</text>`;
  });

  // Legend
  svgContent += `<rect x="${PAD.left}" y="${PAD.top - 20}" width="10" height="3" fill="#334155"/>`;
  svgContent += `<text x="${PAD.left + 14}" y="${PAD.top - 16}" font-size="10" fill="#64748b">— Median</text>`;
  svgContent += `<polygon points="${PAD.left + 90},${PAD.top - 18} ${PAD.left + 95},${PAD.top - 14} ${PAD.left + 90},${PAD.top - 10} ${PAD.left + 85},${PAD.top - 14}" fill="#64748b"/>`;
  svgContent += `<text x="${PAD.left + 99}" y="${PAD.top - 11}" font-size="10" fill="#64748b">Mean  │  Box = IQR  │  Whiskers = 1.5×IQR</text>`;

  svgContent += `</g>`;
  svg.innerHTML = svgContent;
})();
</script>

